mapper.select:
SELECT cycle_id, cycle_code, cycle_name, cycle_type, start_date, end_date, status, create_time
FROM cost_cycle
WHERE cycle_id = #{id}

SELECT cycle_id, cycle_code, cycle_name, cycle_type, start_date, end_date, status, create_time
FROM cost_cycle
WHERE cycle_code = #{cycleCode}

SELECT cycle_id, cycle_code, cycle_name, cycle_type, start_date, end_date, status, create_time FROM cost_cycle
AND cycle_code LIKE CONCAT('%', #{cycleCode}, '%')
AND cycle_name LIKE CONCAT('%', #{cycleName}, '%')
AND cycle_type = #{cycleType}
AND status = #{status}
ORDER BY cycle_code DESC
